import{_ as e,o as a,c as t,a2 as n}from"./chunks/framework.mRCPFc5l.js";const d=JSON.parse('{"title":"Assumptions","description":"","frontmatter":{"title":"Assumptions"},"headers":[],"relativePath":"invariants/assumptions.md","filePath":"invariants/assumptions.md"}'),o={name:"invariants/assumptions.md"};function i(r,s,l,p,c,u){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="assumptions" tabindex="-1">Assumptions <a class="header-anchor" href="#assumptions" aria-label="Permalink to &quot;Assumptions&quot;">​</a></h1><p>Assumptions follow essentially the same <a href="./assertions.html">rules as assertions</a> except they are <em>not</em> negated. This means we can use assumptions to tell the solver to ignore certain potential solutions.</p><p>In this sense an assumption in Fault is basically an <a href="https://en.wikipedia.org/wiki/Axiom#Logical_axioms" target="_blank" rel="noreferrer">axiom</a>. The model must assume that the assumption is always true. If our purpose is formalization or verification, these assumptions are supposed to have been proven correct in another earlier model. In simulation we can take the fact for granted and just use assumptions to eliminate a whole set of potential solutions we do not care about.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume x &gt; 0;</span></span>
<span class="line"><span>assume resources.table &lt;= 4;</span></span>
<span class="line"><span>assume when queue.full then queue.size &gt;= queue.capacity;</span></span></code></pre></div><p>Assumptions accept the same temporal qualifiers as assertions (<code>always</code>, <code>eventually</code>, <code>eventually-always</code>, <code>nmt</code>, <code>nft</code>), and support <code>when/then</code> syntax. See <a href="./assertions.html">Assertions</a> for the full reference.</p><h2 id="constraining-the-solution-space" tabindex="-1">Constraining the Solution Space <a class="header-anchor" href="#constraining-the-solution-space" aria-label="Permalink to &quot;Constraining the Solution Space&quot;">​</a></h2><p>Where an assertion asks Fault to find a scenario where something goes wrong, an assumption rules out scenarios you don&#39;t want the solver to consider. For example, if your model includes a stock that physically can&#39;t go below zero, you can assume that rather than assert it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume pool.instances &gt;= 0;</span></span></code></pre></div><p>Without this, the solver might explore states where <code>instances</code> goes negative — technically satisfying the formula but not meaningful in your system. Assumptions prune those branches away.</p><h2 id="assumptions-in-program-synthesis" tabindex="-1">Assumptions in Program Synthesis <a class="header-anchor" href="#assumptions-in-program-synthesis" aria-label="Permalink to &quot;Assumptions in Program Synthesis&quot;">​</a></h2><p>Assumptions play an additional role in <a href="./../model-types/program-synthesis.html">program synthesis</a>. When the solver is filling <code>__</code> slots by choosing among <code>unfunc</code> definitions, assumptions constrain which solutions are valid. Use <code>assume f available;</code> to guarantee that a function&#39;s precondition is reachable from the initial state — not just that it is defined.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assume process available;</span></span></code></pre></div><p>This tells the solver it must find a sequence where <code>process</code> can actually be called, not just one where it happens to appear.</p>`,14)])])}const m=e(o,[["render",i]]);export{d as __pageData,m as default};
